import math

def check_inequality(n):
    """Checks if (n-3)^3 <= n(n-1)(n-2) for a given n."""
    if n < 4:
        return None
    lhs = (n - 3)**3
    rhs = n * (n - 1) * (n - 2)
    return lhs <= rhs

# Test several values starting from n=4
test_values = range(4, 15)
results = {}
for n in test_values:
    results[n] = check_inequality(n)

print("Results for n=4 to n=14:")
for n, result in results.items():
    print(f"n={n}: {result}")

